// @flow
import React, { useEffect, useState } from 'react';
import { Badge, Button, Card, Col, Form, Modal, Row, Table } from 'react-bootstrap';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import classNames from 'classnames';
import PageTitle from '../../../components/PageTitle';
import { FormInput } from '../../../components';
import Dropdown from 'react-bootstrap/Dropdown';
import { FiArchive, FiClock, FiFilter, FiSun } from 'react-icons/fi';
import { IoCalendarOutline, IoCloseCircleOutline } from 'react-icons/io5';
import { useDispatch, useSelector } from 'react-redux';
import { getAppointmentsAction, rescheduleAppointmentAction } from '../../../redux/appointments/action';
import Spinner from '../../../constants/Spinner';
import { getDoctorsAction } from '../../../redux/actions';
import { decryptMessage, encryptMessage } from '../../../cryptoUtils';
import Select from 'react-select';
import { FcViewDetails } from 'react-icons/fc';
import { useForm } from 'react-hook-form';
import { appointmentStatus } from '../../../utils/DataSets/commonData';
import AppointmentCalendar from './AppointmentCalendar';
import { FaCalendar, FaCalendarWeek, FaRegListAlt } from 'react-icons/fa';
import { LucideCalendarDays } from 'lucide-react';
import { CiCalendar } from 'react-icons/ci';
import Paginations from '../../../helpers/Paginations';
import { formatDateByUserTimeZone } from '../../../components/timeZonePipe';
// const clinicId = JSON.parse(sessionStorage.getItem('hyper_user'))?.clinicId;
const clinicId = decryptMessage(localStorage?.getItem('subClinicLocation')) || '';




// Component for Appointments List Table
const AppointmentsList = ({
    appointmentPeriod,
    setSkip,
    skip,
}): React$Element<React$FragmentType> => {
    const store = useSelector((state) => state);
    const dispatch = useDispatch();
    const appointmentsList = store?.getAppointmentsReducer?.data?.appointments;
    const [cancelationPopupRow, setCancelationPopupRow] = useState(null);
    const [cancelationReason, setCancelationReason] = useState('');
    const [selectedStatus, setSelectedStatus] = useState('');
    const updateSuccess = store?.rescheduleAppointmentReducer?.data?.status;
    const {
        handleSubmit,
        formState: { errors },
    } = useForm();
    useEffect(() => {
        if (updateSuccess === 200) {
            dispatch(getAppointmentsAction({ clinicId: clinicId, status: appointmentPeriod, skip: skip, limit: 10 }));
            setCancelationPopupRow(null);
            setCancelationReason('');
        }
    }, [updateSuccess]);
    const formatTimeWithAmPm = (isoString) => {
        if (!isoString) return '';
        const date = new Date(isoString);
        return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: true });
    };

    useEffect(() => {
        const handleClickOutside = (e) => {
            // Check if the click target is NOT inside the popup
            if (!e.target.closest('.cancellation-popup') && cancelationPopupRow !== null) {
                setCancelationPopupRow(null); // Close popup
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [cancelationPopupRow]);

    const submitWithReason = (data) => {
        const payload = {
            cancellationReason: [
                {
                    coding: [
                        {
                            system: '',
                            code: '',
                            display: cancelationReason,
                        },
                    ],
                    text: cancelationReason, // use display text
                },
            ],
            status: 'cancelled',
        };
        dispatch(
            rescheduleAppointmentAction({
                id: cancelationPopupRow,
                key: encryptMessage(payload),
            })
        );
    };
    const handlePageChange = (pageNumber) => {
        setSkip(pageNumber);
    };
    return (
        <div className="scroll-container mt-2" style={{ height: '69vh', overflowY: 'auto' }}>
            <Table responsive className="table-centered mb-0  rounded">
                <thead className="text-white">
                    <tr>
                        <th className="text-white">Sr.No.</th>
                        <th className="text-white">Status</th>
                        <th className="text-white">Patient</th>
                        <th className="text-white">Booked Slot</th>
                        <th className="text-white">Date</th>
                        <th className="text-white">Provider</th>
                        {/* <th className='text-white'>Doctor Department</th> */}
                        <th className="text-white">Type</th>
                        <th className="text-white">Reason</th>
                        <th className="text-white">Action</th>
                    </tr>
                </thead>
                <tbody className="">
                    {store?.getAppointmentsReducer?.loading ? (
                        <tr>
                            <td colSpan={9} className="text-center">
                                <Spinner />
                            </td>
                        </tr>
                    ) : appointmentsList?.length === 0 ? (
                        <tr>
                            <td colSpan={9} className="text-center">
                                <h5>No Appointments Found</h5>
                            </td>
                        </tr>
                    ) : (
                        appointmentsList &&
                        appointmentsList?.map((data, index) => (
                            <tr key={index}>
                                <td>{index + 1}</td>
                                <td className="text-capitalize position-relative">
                                    <Form.Select
                                        defaultValue={data?.status}
                                        onChange={(e) => {
                                            setSelectedStatus(e.target.value);
                                            if (e.target.value === 'cancelled') {
                                                setCancelationPopupRow(data?._id); // or use data?._id if preferred
                                            } else {
                                                dispatch(
                                                    rescheduleAppointmentAction({
                                                        id: data?._id,
                                                        key: encryptMessage({ status: e.target.value }),
                                                    })
                                                );
                                                setCancelationPopupRow(null); // close popup if status changes again
                                            }
                                        }}
                                        className={`schedule-status-select
                                         ${data?.status === 'pending' && 'pendingColor'}
                                         ${data?.status === 'proposed' && 'proposedColor'}
                                         ${data?.status === 'booked' && 'bookedColor'}
                                         ${data?.status === 'arrived' && 'arrivedColor'}
                                         ${data?.status === 'fulfilled' && 'fulfilledColor'}
                                         ${data?.status === 'cancelled' && 'cancelledColor'}
                                         ${data?.status === 'noshow' && 'noshowColor'}
                                         ${data?.status === 'entered-in-error' && 'enteredinerrorColor'}
                                         ${data?.status === 'checked-in' && 'checkedinColor'}
                                         ${data?.status === 'waitlist' && 'waitlistColor'}
                                         `}>
                                        {appointmentStatus?.map((data, index) => (
                                            <option value={data?.code} key={index}>
                                                {' '}
                                                {data?.display}
                                            </option>
                                        ))}
                                    </Form.Select>
                                    {cancelationPopupRow === data?._id && (
                                        <div
                                            className="position-absolute cancellation-popup border   bg-white"
                                            style={{
                                                left: '84%',
                                                top: '0%',
                                                width: '14vw',
                                                boxShadow: '0 3px 6px rgba(0,0,0,0.16), 0 3px 6px rgba(0,0,0,0.23)',
                                            }}>
                                            <p className="fs-4 px-2 mb-0 text-end ">
                                                <IoCloseCircleOutline
                                                    onClick={() => {
                                                        setCancelationPopupRow(null);
                                                    }}
                                                />
                                            </p>
                                            <div className=" p-2 pt-0">
                                                <Form onSubmit={handleSubmit(submitWithReason)}>
                                                    <Form.Group>
                                                        <Form.Label>Cancelation Reason</Form.Label>
                                                        <Form.Control
                                                            className="mb-2"
                                                            onChange={(e) => setCancelationReason(e.target.value)}
                                                            type="text"
                                                            placeholder="Enter the cancellation reason"
                                                        />
                                                    </Form.Group>
                                                    <div className="text-end">
                                                        <Button
                                                            disabled={!cancelationReason}
                                                            className="custom-buttons"
                                                            type="submit">
                                                            Submit
                                                        </Button>
                                                    </div>
                                                </Form>
                                            </div>
                                        </div>
                                    )}
                                </td>
                                <td className="text-capitalize">
                                    {(data?.subject?.name?.[0]?.prefix?.[0]
                                        ? data?.subject?.name?.[0]?.prefix?.[0] + ' '
                                        : '') +
                                        (data?.subject?.name?.[0]?.family || '') +
                                        (data?.subject?.name?.[0]?.given?.length > 0
                                            ? ' ' + data?.subject?.name?.[0]?.given?.join(' ')
                                            : '') || 'N/A'}
                                    <div className="d-flex gap-2">
                                        <span>
                                            {data?.subject?.birthDate
                                                ? formatDateByUserTimeZone(data.subject.birthDate, {}, 'date')
                                                : 'N/A'}
                                        </span>
                                        <span>
                                            {data?.subject?.telecom?.find(
                                                (item) => item.system === 'phone' && item.value
                                            )?.value || 'Phone number not available'}
                                        </span>
                                    </div>
                                </td>
                                <td>
                                    {formatDateByUserTimeZone(data?.start, {}, 'time')} - {formatDateByUserTimeZone(data?.end, {}, 'time')}
                                </td>

                                <td>{formatDateByUserTimeZone(data?.date, {}, 'date')}</td>
                                <td>{data?.doctorId?.prefix?.[0] || '' + data?.doctorId?.name?.[0]?.text || 'N/A'}</td>
                                <td
                                    className="text-capitalize cursor-pointer"
                                    data-toggle="tooltip"
                                    data-placement="top"
                                    title={data?.appointmentType?.coding?.[0]?.display}>
                                    {data?.appointmentType?.coding?.[0]?.display
                                        ? data?.appointmentType?.coding?.[0]?.display?.length > 20
                                            ? data?.appointmentType?.coding?.[0]?.display?.slice(0, 19) + '...'
                                            : data?.appointmentType?.coding?.[0]?.display
                                        : 'N/A'}
                                </td>
                                <td
                                    className="text-capitalize cursor-pointer"
                                    data-toggle="tooltip"
                                    data-placement="top"
                                    title={data?.reason?.[0]?.coding?.[0]?.display || 'N/A'}>
                                    {data?.reason?.[0]?.coding?.[0]?.display
                                        ? data?.reason?.[0]?.coding?.[0]?.display?.length > 20
                                            ? data?.reason?.[0]?.coding?.[0]?.display?.slice(0, 19) + '...'
                                            : data?.reason?.[0]?.coding?.[0]?.display
                                        : 'N/A'}
                                </td>
                                <td>
                                    <Link
                                        to={`/apps/appointments/newAppointment?updateid=${data?._id}`}
                                        className="action-icon fs-5">
                                        <i className="mdi mdi-square-edit-outline cursor-pointer"></i>
                                    </Link>
                                </td>
                            </tr>
                        ))
                    )}
                </tbody>
            </Table>
            <div className="col-12">
                <div className="mt-2 d-flex justify-content-end">
                    <Paginations
                        currentPage={skip}
                        totalPages={store?.getAppointmentsReducer?.data?.pagination?.totalPages}
                        onPageChange={handlePageChange}
                    />
                </div>
            </div>
        </div>
    );
};

// Main Appointments Component
const Appointments = (): React$Element<React$FragmentType> => {
    const {
        register,
        formState: { errors },
        setValue,
        clearErrors,
    } = useForm();

    const [activeTab, setActiveTab] = useState('appointmentCalendar');
    const [appointmentPeriod, setAppointmentPeriod] = useState('today');
    const store = useSelector((state) => state);
    const dispatch = useDispatch();
    const [selectedDoctor, setSelectedDoctor] = useState(null);
    const [doctorSearch, setDoctorSearch] = useState('');
    const [skip, setSkip] = useState(1);
    const doctorDetails = store?.getDoctorsReducer?.data?.result;
    const doctorOptions = doctorDetails?.map((data) => ({
        value: data?._id,
        label: (data?.name?.[0]?.prefix?.[0]
            ? data?.name?.[0]?.prefix?.[0] + ' '
            : '') +
            (data?.name?.[0]?.family || '') +
            (data?.name?.[0]?.given?.length > 0
                ? ' ' + data?.name?.[0]?.given?.join(' ')
                : '') + ' ' +
            (data?.identifier?.find((tel) => tel?.type?.coding?.[0]?.code === 'NPI')?.value ?
                `(******${data?.identifier?.find((tel) => tel?.type?.coding?.[0]?.code === 'NPI')?.value.slice(-4)})`
                : '') || ''
    }));
    useEffect(() => {
        const doctorPayload = { status: true, search: doctorSearch };
        dispatch(getDoctorsAction(doctorPayload));
    }, [dispatch, doctorSearch]);
    useEffect(() => {
        if (activeTab === 'appointments') {
            dispatch(
                getAppointmentsAction({
                    clinicId: clinicId,
                    doctorId: selectedDoctor?.value || '',
                    status: appointmentPeriod,
                    skip: skip,
                    limit: 10,
                })
            );
        }
    }, [dispatch, selectedDoctor, appointmentPeriod, activeTab, skip]);
    const handleInputChange = (data, type) => {
        setDoctorSearch(data);
    };

    const handleChange = (selectedOption, type) => {
        setSelectedDoctor(selectedOption, 'Selected Option');
    };
    const statusColors = {
        pending: '#f1c40f', // Yellow
        proposed: '#3498db', // Blue
        booked: '#2ecc71', // Green
        arrived: '#27ae60', // Dark Green
        fulfilled: '#9b59b6', // Purple
        cancelled: '#e74c3c', // Red
        noshow: '#e67e22', // Oranges
        enteredinerror: '#95a5a6', // Grey
        checkedin: '#1abc9c', // Teal
        waitlist: '#8e44ad', // Dark Purple
    };
    const [showTooltip, setShowTooltip] = useState(false);

    return (
        <>
            <Row className="mt-2">
                <Col xs={12} className="px-0">
                    <Card className="scroll-container page-height">
                        <Card.Body className="p-2">
                            <Row className="">
                                <Col className="px-0">
                                    <ul className="nav nav-underline">
                                        <li className="nav-item ms-md-2">
                                            <span
                                                className={classNames(
                                                    'nav-link fw-bold text-black cursor-pointer fs-6',
                                                    {
                                                        active: activeTab === 'appointmentCalendar',
                                                        'fw-bold fs-6': activeTab === 'appointmentCalendar',
                                                    }
                                                )}
                                                onClick={() => setActiveTab('appointmentCalendar')}>
                                                <CiCalendar /> {`Appointment Calendar`}
                                            </span>
                                        </li>
                                        <li className="nav-item">
                                            <span
                                                className={classNames(
                                                    'nav-link fw-bold text-black cursor-pointer fs-6',
                                                    {
                                                        active: activeTab === 'appointments',
                                                        'fw-bold fs-6': activeTab === 'appointments',
                                                    }
                                                )}
                                                onClick={() => setActiveTab('appointments')}>
                                                <FaRegListAlt /> {`Appointment List`}
                                            </span>
                                        </li>
                                    </ul>
                                </Col>

                                <Col className="text-end mt-2 mt-md-0">
                                    <Row className="gy-2 gx-2 align-items-center justify-content-xl-end justify-content-between">
                                        <Col
                                            xs={1}
                                            className="position-relative d-flex align-items-center justify-content-end text-end">
                                            {/* <div
                                                > */}
                                            <FcViewDetails
                                                onMouseEnter={() => setShowTooltip(true)}
                                                onMouseLeave={() => setShowTooltip(false)}
                                                className="fs-3 text-dark"
                                                style={{ cursor: 'help' }}
                                            />
                                            {/* </div> */}

                                            {showTooltip && (
                                                <div className="color-legend-tooltip">
                                                    <div className="d-flex gap-3">
                                                        <div
                                                            className="d-flex flex-column gap-2"
                                                            style={{ width: '50%' }}>
                                                            {Object.entries(statusColors)
                                                                .slice(
                                                                    0,
                                                                    Math.ceil(Object.entries(statusColors).length / 2)
                                                                )
                                                                .map(([status, color]) => (
                                                                    <div
                                                                        key={status}
                                                                        className="d-flex align-items-center gap-1">
                                                                        <div
                                                                            style={{
                                                                                width: '12px',
                                                                                height: '12px',
                                                                                borderRadius: '10%',
                                                                                backgroundColor: color,
                                                                                border: '1px solid #ccc',
                                                                            }}
                                                                        />
                                                                        <span
                                                                            className="text-capitalize"
                                                                            style={{ fontSize: '12px' }}>
                                                                            {status}
                                                                        </span>
                                                                    </div>
                                                                ))}
                                                        </div>

                                                        <div
                                                            className="d-flex flex-column gap-2"
                                                            style={{ width: '50%' }}>
                                                            {Object.entries(statusColors)
                                                                .slice(
                                                                    Math.ceil(Object.entries(statusColors).length / 2)
                                                                )
                                                                .map(([status, color]) => (
                                                                    <div
                                                                        key={status}
                                                                        className="d-flex align-items-center gap-1">
                                                                        <div
                                                                            style={{
                                                                                width: '12px',
                                                                                height: '12px',
                                                                                borderRadius: '10%',
                                                                                backgroundColor: color,
                                                                                border: '1px solid #ccc',
                                                                            }}
                                                                        />
                                                                        <span
                                                                            className="text-capitalize"
                                                                            style={{ fontSize: '12px' }}>
                                                                            {status}
                                                                        </span>
                                                                    </div>
                                                                ))}
                                                        </div>
                                                    </div>
                                                </div>
                                            )}
                                        </Col>
                                        <Col
                                            sm="auto"
                                            className="d-flex flex-wrap gap-2 align-items-center text-start justify-content-between responnsible-party-select px-0">
                                            <Select
                                                className="basic-single"
                                                classNamePrefix="select"
                                                isLoading={store?.getDoctorsReducer?.loading}
                                                isClearable={true}
                                                value={selectedDoctor}
                                                isSearchable={true}
                                                {...register('selectedDoctor')}
                                                onInputChange={(inputValue) => handleInputChange(inputValue, 'doctor')}
                                                onChange={(data) => {
                                                    setValue('selectedDoctor', data);
                                                    handleChange(data, 'doctor');
                                                    clearErrors('selectedDoctor');
                                                }}
                                                name="doctorName"
                                                options={doctorOptions}
                                                placeholder="Select Provider"
                                                styles={{
                                                    control: (provided) => ({
                                                        ...provided,
                                                        minHeight: '30px',
                                                        height: '30px',
                                                        width: '200px',
                                                        padding: '0px 0px 0px 7px',
                                                        fontSize: '10px',
                                                        border: '0px',
                                                        backgroundColor: '#E8F0FE!important',
                                                        boxShadow: 'none',
                                                    }),
                                                    valueContainer: (provided) => ({
                                                        ...provided,
                                                        padding: '0px',
                                                    }),
                                                    input: (provided) => ({
                                                        ...provided,
                                                        margin: '0px',
                                                    }),
                                                    indicatorsContainer: (provided) => ({
                                                        ...provided,
                                                        height: '30px',
                                                    }),
                                                    placeholder: (provided) => ({
                                                        ...provided,
                                                        fontWeight: 600,
                                                        color: '#0908084f',
                                                    }),
                                                    option: (provided, state) => ({
                                                        ...provided,
                                                        backgroundColor: state.isFocused ? '#b9bcbe44' : '',
                                                        fontSize: state.isFocused ? '10px' : '10px',
                                                        color: 'black',
                                                        padding: '10px 12px',
                                                        cursor: 'pointer',
                                                        zIndex: 9999,
                                                    }),
                                                    menu: (provided) => ({
                                                        ...provided,
                                                        zIndex: 9999, // 🔥 z-index for dropdown itself
                                                    }),
                                                    menuPortal: (provided) => ({
                                                        ...provided,
                                                        zIndex: 9999, // 🔥 z-index if using portal
                                                    }),
                                                }}
                                                menuPlacement="auto"
                                                menuPosition="fixed"
                                            />

                                            {/* Additional controls shown only in the "Appointments" tab */}
                                            {activeTab === 'appointments' && (
                                                <>
                                                    <Button className="custom-buttons">
                                                        <FiFilter className="fs-5" />
                                                    </Button>
                                                    <Button
                                                        as={Link}
                                                        to="/apps/appointments/newAppointment"
                                                        className="custom-buttons">
                                                        New Appointment
                                                    </Button>
                                                </>
                                            )}
                                        </Col>
                                    </Row>
                                </Col>

                                {activeTab === 'appointments' && (
                                    <Col md={12} className="mt-2">
                                        <div className="time-period-tabs">
                                            <ul className="nav nav-pills">
                                                <li className="nav-item">
                                                    <button
                                                        className={`nav-link ${appointmentPeriod === 'today' ? 'active' : 'text-black'
                                                            }`}
                                                        onClick={() => setAppointmentPeriod('today')}>
                                                        <FiSun className="me-1" />
                                                        Today
                                                    </button>
                                                </li>
                                                <li className="nav-item ms-2">
                                                    <button
                                                        className={`nav-link ${appointmentPeriod === 'upcoming' ? 'active' : 'text-black'
                                                            }`}
                                                        onClick={() => setAppointmentPeriod('upcoming')}>
                                                        <FiClock className="me-1" />
                                                        Upcoming
                                                    </button>
                                                </li>
                                                <li className="nav-item ms-2">
                                                    <button
                                                        className={`nav-link ${appointmentPeriod === 'history' ? 'active' : 'text-black'
                                                            }`}
                                                        onClick={() => setAppointmentPeriod('history')}>
                                                        <FiArchive className="me-1" />
                                                        History
                                                    </button>
                                                </li>
                                            </ul>
                                        </div>
                                    </Col>
                                )}
                            </Row>

                            {/* Render table based on active tab */}
                            {activeTab === 'appointments' ? (
                                <AppointmentsList
                                    setSkip={setSkip}
                                    skip={skip}
                                    appointmentPeriod={appointmentPeriod}
                                />
                            ) : (
                                <AppointmentCalendar
                                    appointmentPeriod={appointmentPeriod}
                                    selectedDoctor={selectedDoctor?.value}
                                />
                            )}
                        </Card.Body>
                    </Card>
                </Col>
            </Row>
        </>
    );
};

export default Appointments;
